package com.jjt.ingsis.printscript.operations

import com.jjt.ingsis.printscript.formatting.RuleViolation
import java.time.Instant
import java.util.UUID

enum class OperationKind { LINT, FORMAT }

enum class OperationState { PENDING, RUNNING, CANCELLING, COMPLETED, FAILED, CANCELLED }

// Generated by the caller before any remote I/O; the entire command is immutable on retries.
data class OperationCommand(
    val kind: OperationKind,
    val version: String,
    val code: String,
    val rules: Map<String, Any?>,
    val processorRevision: String,
    val submittedAt: Instant,
)

data class OperationDiagnostic(
    val rule: String,
    val message: String,
    val line: Int,
    val column: Int,
)

data class OperationOutput(
    val outcome: String,
    val code: String? = null,
    val diagnostics: List<OperationDiagnostic> = emptyList(),
    val violations: List<RuleViolation> = emptyList(),
)

data class OperationRecord(
    val id: UUID,
    val command: OperationCommand?,
    val state: OperationState,
    val owner: UUID? = null,
    val output: OperationOutput? = null,
    val reason: String? = null,
)

val OperationRecord.terminal: Boolean
    get() = state in setOf(OperationState.COMPLETED, OperationState.FAILED, OperationState.CANCELLED)

sealed interface OperationReply {
    data class Found(
        val operation: OperationRecord,
    ) : OperationReply

    data object Missing : OperationReply

    data object Conflict : OperationReply

    data object Expired : OperationReply

    data object Invalid : OperationReply

    data object Full : OperationReply
}

interface OperationStore {
    fun find(id: UUID): OperationRecord?

    fun insert(record: OperationRecord): Boolean

    fun replace(
        before: OperationRecord,
        after: OperationRecord,
    ): Boolean

    fun pending(): List<UUID>
}

class OperationStoreUnavailable(
    cause: Throwable,
) : RuntimeException(cause)
